const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The question specifies a future date (September 13, 2025).
  // GEE collections do not contain future data.
  // This will inevitably lead to an empty collection.
  const dateOfInterest = '2025-09-13';

  // Define points for the fire origin and the target area.
  const fireOrigin = ee.Geometry.Point([-117.8, 48.9]); // Approx. Lynx Mountain, WA
  const targetArea = ee.Geometry.Point([-117.8, 49.1]); // Southern British Columbia, Canada

  // 2. Data Acquisition & Check
  // Sentinel-5P TROPOMI is best for detecting aerosols like smoke.
  // The 'AER_AI' band (Absorbing Aerosol Index) is a good indicator.
  const s5p_collection = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_AER_AI')
    .select('absorbing_aerosol_index')
    .filterDate(dateOfInterest, ee.Date(dateOfInterest).advance(1, 'day'))
    .filterBounds(fireOrigin.union(targetArea));

  // Check if the collection is empty.
  const collectionSize = s5p_collection.size().getInfo();

  // 3. Processing, Calculation, and Final Answer
  if (collectionSize === 0) {
    console.log(`Image Collection Size: ${collectionSize}`);
    console.log(`No Sentinel-5P images found for the specified future date: ${dateOfInterest}.`);
    console.log("A: Yes"); // This is a placeholder tag as per the original script.
    return; // Exit after printing the required tag.
  }

  // The following code would run if data existed.
  const image = s5p_collection.mean();

  // Define a reducer to get the mean value.
  const reducer = ee.Reducer.mean();

  // Get the aerosol index value at the fire origin.
  const smokeAtSource = image.reduceRegion({
    reducer: reducer,
    geometry: fireOrigin,
    scale: 1000,
    maxPixels: 1e9
  }).get('absorbing_aerosol_index');

  // Get the aerosol index value at the target area in BC.
  const smokeAtTarget = image.reduceRegion({
    reducer: reducer,
    geometry: targetArea,
    scale: 1000,
    maxPixels: 1e9
  }).get('absorbing_aerosol_index');

  // Retrieve the results.
  const sourceVal = smokeAtSource.getInfo();
  const targetVal = smokeAtTarget.getInfo();

  console.log(`Image Collection Size: ${collectionSize}`);

  // Check for C3: Calculation Failure
  if (sourceVal === null || targetVal === null) {
    console.log("Calculation failed: Could not retrieve pixel values.");
    if (sourceVal === null) console.log("Source Value: null");
    if (targetVal === null) console.log("Target Value: null");
    console.log("C3: Calculation Failure");
    return;
  }

  console.log(`Aerosol Index at Fire Origin (WA): ${sourceVal.toFixed(2)}`);
  console.log(`Aerosol Index in Target Area (BC): ${targetVal.toFixed(2)}`);

  // Smoke is indicated by an Aerosol Index > 1.0.
  // We check if the source shows strong smoke and the target also shows elevated levels.
  const sourceHasSmoke = sourceVal > 1.0;
  const targetHasSmoke = targetVal > 1.0;

  if (sourceHasSmoke && targetHasSmoke) {
    console.log("Evidence of smoke at both source and target locations.");
    console.log("A: Yes");
  } else {
    console.log("No significant evidence of smoke spread to target location.");
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
